def solve():
    MOD = 1073741824

    # Precompute divisor function d(n) for n up to 100*100*100 = 1e6
    max_n = 100 * 100 * 100
    d = [0] * (max_n + 1)

    # Compute d(n) for all n up to max_n
    for i in range(1, max_n + 1):
        temp = i
        count = 0
        f = 1
        for p in range(2, int(temp**0.5) + 1):
            if temp % p == 0:
                cnt = 0
                while temp % p == 0:
                    cnt += 1
                    temp //= p
                f *= (cnt + 1)
            if temp == 1:
                break
        if temp > 1:
            f *= 2
        d[i] = f

    # For each i, j, k, we want to compute d(i*j*k)
    a, b, c = map(int, input().split())

    result = 0
    for i in range(1, a + 1):
        for j in range(1, b + 1):
            for k in range(1, c + 1):
                product = i * j * k
                if product > max_n:
                    continue
                result = (result + d[product]) % MOD

    print(result)

solve()
